    int fd = open("/proc/self/fd/0", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    // /proc/self/fd/0 のファイルサイズを取得する
    struct stat sb;
    fstat(fd, &sb);

    // /proc/self/fd/0 のファイルをマッピングする
